# (feastDate, English name, Turkish name, Turkish description, Turkish patronOf) - the original English seed saints, second part
DATA = [
    ("January 6", "Saint André Bessette (Brother André)", "Aziz André Bessette (Kardeş André)", "Aziz Yusuf'a derin bağlılığı ve Montreal'deki Notre Dame Koleji'nde alçakgönüllü kapıcılığıyla tanınan Kutsal Haç Cemaati'nin Kanadalı kardeşi; duaları sayesinde bildirilen şifalarla ünlendi. Dünyanın en büyük Aziz Yusuf hac merkezlerinden biri olan Mount Royal'daki Aziz Yusuf Oratory'sini kurdu. 2010'da Papa XVI. Benedictus tarafından aziz ilan edildi.", "Aziz Yusuf Oratory'si, kapıcılar, bakıcılar"),
    ("May 2", "Saint Athanasius of Alexandria", "İskenderiyeli Aziz Athanasius", "Kilise Doktoru ve İskenderiye Piskoposu; dördüncü yüzyılda İznik inancının Ariusçu sapkınlığa karşı başlıca savunucusu. Mesih'in tamamen tanrısal ve Baba ile aynı özden olduğunda ısrar ettiği için Ariusçu imparatorlar ve piskoposlarca beş kez sürgüne gönderildi; toplam on yedi yıldan fazla İskenderiye'den uzak kaldı. 'Enkarnasyon Üzerine'yi ve Aziz Anthony'nin Hayatı'nı yazdı; Roma Katolik ve Ortodoks geleneklerinde Doğu Kilisesi'nin dört büyük Doktoru'ndan biri olarak onurlandırılır.", "İlahiyatçılar, İskenderiye"),
    ("January 2", "Saint Seraphim of Sarov", "Sarov'lu Aziz Seraphim", "On sekizinci yüzyılın ortalarında Rusya'nın Kursk kentinde Prokhor Moshnin olarak doğan Sarov Manastırı'nın Rus Ortodoks keşişi, münzevisi ve ruhsal yaşlısı (starets). Yıllarca ormanda yalnız yaşadı, sonra kendisini arayan birçok hacıya rehberlik etmek üzere döndü; Hıristiyan yaşamının hedefinin 'Kutsal Ruh'u edinmek' olduğunu öğretti. 1833'te öldü ve 1903'te Rus Ortodoks Kilisesi tarafından aziz ilan edildi.", "Rusya, keşişler"),
    ("January 17", "Saint Anthony the Great", "Büyük Aziz Anthony", "Hıristiyan manastırcılığının babası sayılan Mısırlı Çöl Babası. Yirmi yaşlarında mirasını verip dua ve çilecilik hayatı için çöle çekildi, sonra çok sayıdaki takipçisini gevşek bir manastır topluluğu halinde örgütledi. Aziz Athanasius'un Anthony'nin Hayatı eseri örneğini Hıristiyan dünyasına yaydı; özellikle adını taşıyan Mısır'ın Doğu Çölü'ndeki manastırı hâlâ canlı bir ruhsal merkez olan Kıpti Ortodoks Kilisesi'nde kurucu baba olarak onurlandırılır.", "Keşişler, mezarcılar, sepet örenler, cilt hastalıkları"),
    ("November 9", "Saint Nektarios of Aegina", "Aegina'lı Aziz Nektarios", "Pentapolis Metropoliti olarak hizmet ettikten sonra haksız suçlamalara ve görevden alınmaya alçakgönüllülükle ve şikâyet etmeden katlanan Yunan Ortodoks piskoposu, ilahiyatçı ve mucize yapan. Sonra Aegina adasında Kutsal Teslis Manastırı'nı kurdu ve son yıllarını dua, yazı ve ruhsal rehberlikle geçirdi. Özellikle kanser hastaları arasında şifa mucizeleriyle yaygın biçimde onurlandırılan kendisi, 1961'de İstanbul Ekümenik Patrikhanesi tarafından aziz ilan edildi.", "Hastalar, kanser hastaları, Aegina"),
    ("September 24", "Saint Silouan the Athonite", "Athos'lu Aziz Silouan", "Tambov bölgesinde Semyon Antonov olarak doğan Athos Dağı Aziz Panteleimon Manastırı'nın Rus Ortodoks keşişi. Yıllarca süren yoğun ruhsal mücadeleden sonra Mesih'ten, öğretisini sonraki hayatı boyunca şekillendiren bir güvence aldı: 'Aklını cehennemde tut ve umutsuzluğa kapılma.' Öğrencisi Başrahip Sophrony'nin koruduğu konuşmaları ve yazıları modern Ortodoks maneviyatının etkili metinleri oldu. 1987'de İstanbul Ekümenik Patrikhanesi tarafından aziz ilan edildi.", "Athos Dağı, keşişler, ruhsal yazarlar"),
    ("September 3", "Saint Gregory the Great", "Büyük Aziz Gregorius", "590-604 arasında papa ve Kilise Doktoru; Augustinus, Ambrosius ve Jerome ile birlikte Batı Kilisesi'nin dört büyük Doktoru'ndan biri. Roma litürjisini ve ilahilerini (sonradan Gregoryen Ilahisi) ıslah etti, Aziz Augustinus of Canterbury'yi İngiltere'yi müjdelemek için gönderdi ve çobanlık bakımı ve Kutsal Yazılar üzerine kapsamlı yazılar yazarak kendine 'Tanrı'nın Kullarının Kulu' unvanını aldı.", "Müzisyenler, şarkıcılar, öğretmenler, öğrenciler, İngiltere"),
    ("June 28", "Saint Irenaeus of Lyons", "Lyon'lu Aziz Irenaeus", "İkinci yüzyılda Lyon Piskoposu ve kendisi Havari Yuhanna tarafından öğretilen Aziz Polycarp'ın öğrencisi. Başlıca eseri Sapkınlıklara Karşı, Gnostisizmin sistematik bir çürütmesini ve havarisel geleneğin savunmasını sunarak onu ilk büyük Hıristiyan ilahiyatçılarından biri yaptı. Papa Franciscus 2022'de onu, Doğu ve Batı kiliselerinin paylaştığı ortak imana tanıklığı için 'Birlik Doktoru' unvanıyla Kilise Doktoru ilan etti.", "İlahiyatçılar, savunmacılar, Hıristiyan birliği"),
    ("June 22", "Saint Thomas More", "Aziz Thomas More", "Kral VIII. Henry döneminde Lord Şansölye olarak görev yapan İngiliz hukukçu, bilgin ve devlet adamı. Dürüstlüğü, zekâsı ve Utopia adlı eseriyle ünlüdür; kralı İngiltere'de Kilise'nin en üst başkanı olarak tanımayı reddettiği için Londra Kulesi'nde hapsedildi ve 1535'te başı kesildi; kendini 'kralın iyi hizmetkârı ama önce Tanrı'nın' olarak ilan etti. 1935'te Papa XI. Pius tarafından aziz ilan edildi.", "Hukukçular, devlet adamları, siyasetçiler"),
    ("December 4", "Saint John of Damascus", "Şamlı Aziz Yuhanna", "Emevi sarayında hizmet eden önde gelen bir Hıristiyan aileden Şam'da doğan, sonra Kudüs yakınındaki Aziz Sabbas manastırına çekilen sekizinci yüzyıl Doğulu keşişi, rahibi ve ilahiyatçısı. İkonoklazma tartışması sırasında ikonlara saygının büyük savunucusu olarak anılır; 'Ortodoks İmanın Kesin Açıklaması' adlı eseri Yunan Babaları'nın ilahiyatını yüzyıllar boyunca özetledi. Roma Katolik geleneğinde Kilise Doktoru, Doğu Ortodoksluğunda büyük Kilise Babalarından biri olarak onurlandırılır.", "İlahiyatçılar, ikon ressamları"),
    ("March 21", "Thomas Cranmer", "Thomas Cranmer", "Canterbury Başpiskoposu (1489-1556) ve dili yüzyıllarca İngilizce konuşan ibadetini şekillendiren ilk Duaların Ortak Kitabı'nın (1549) başlıca yazarı. Kraliçe I. Mary döneminde hapsedildi ve 21 Mart 1556'da Oxford'da kazığa bağlanıp yakıldı.", "Anglikan Cemaati, litürji yazarları"),
    ("July 28", "Johann Sebastian Bach", "Johann Sebastian Bach", "Eserlerini Soli Deo Gloria, 'yalnız Tanrı'ya yücelik', ile adayan Alman Lutheran besteci ve orgcu (1685-1750). Leipzig'de kantor olarak hizmet etti; yüzlerce kilise kantatı, Çile Kantatları ve Si minör Ayin'i yazdı. Lutheran ve Anglikan kiliseleri tarafından ölüm gününde anılır.", "Kilise müzisyenleri, orgcular, besteciler"),
    ("May 27", "John Calvin", "John Calvin", "Cenevre'de Reform'a önderlik eden Fransız reformcu ve ilahiyatçı (1509-1564). Hıristiyan Dininin Esasları adlı eseri Reformed ve Presbiteryen ilahiyatın temeli oldu. Reformed kiliseler tarafından ölüm gününde anılır.", "Reformed ve Presbiteryen kiliseler"),
    ("December 21", "John Newton", "John Newton", "Köle gemisi kaptanıyken Anglikan rahibe dönüşen İngiliz (1725-1807). 1748'de denizde şiddetli bir fırtınanın ardından imana yöneldi, birkaç yıl sonra köle ticaretini bıraktı ve sonunda ona açıkça karşı çıkanlardan biri oldu. 'Amazing Grace' ilahisini yazdı.", "İlahi yazarları, bağışlanma arayanlar"),
    ("July 30", "William Wilberforce", "William Wilberforce", "Evanjelik dönüşümünün ardından köle ticaretine karşı uzun parlamento kampanyasına önderlik eden İngiliz siyasetçi ve Anglikan meslekten olmayan kişi (1759-1833). Köle Ticareti Yasası 1807'de çıktı. Parlamento, Britanya İmparatorluğu genelinde köleliğin kaldırılmasını sonuçlandırırken Temmuz 1833'te öldü.", "Köleliğe karşı kampanya yürütenler, reformcular"),
    ("April 1", "Saint Mary of Egypt", "Mısırlı Aziz Meryem", "Köklü tövbenin örneği olarak onurlandırılan beşinci yüzyıl Mısırlı çilekeşi. İskenderiye'de yıllarca dağınık bir yaşamın ardından Kudüs'te Kutsal Mezar Kilisesi'ne girmesi mucizevi biçimde engellendi ve dönüşüme yöneldi; Ürdün'ün ötesindeki çöle yalnız çekilip on yıllarca dua ve tövbe etti. Yaşamının sonuna doğru keşiş Zosimas onu buldu, ona Kutsal Komünyon verdi ve sonra bir aslanın yardımıyla bedenini gömdü. Doğu Ortodoks Kilisesi'nin en çok onurlandırılan azizlerindendir; hayatı Büyük Oruç'un beşinci haftasında Matins'te tam olarak okunur.", "Tövbe edenler, geçmiş günah ya da bağımlılıkla mücadele edenler"),
    ("April 21", "Saint Anselm of Canterbury", "Canterbury'li Aziz Anselm", "İtalya doğumlu Benedikten keşiş ve Canterbury Başpiskoposu; Skolastisizmin babası sayılır. Proslogion'da Tanrı'nın varlığına dair ünlü 'ontolojik argümanı' formüle etti, Cur Deus Homo'da Kefaret üzerine etkili bir anlatım geliştirdi. 1720'de Papa XI. Clement tarafından Kilise Doktoru ilan edildi.", "İlahiyatçılar, filozoflar"),
    ("April 25", "Saint Mark the Evangelist", "Müjdeci Aziz Markus", "İkinci İncil'in yazarı; geleneksel olarak Elçilerin İşleri'ndeki, Aziz Pavlus ve Aziz Barnaba'ya eşlik eden ve sonra Roma'da Aziz Petrus'a yardım eden Yuhanna Markus ile özdeşleştirilir. Eski gelenek, Mısır'daki İskenderiye Kilisesi'ni kurduğunu söyler; Kıpti Ortodoks Kilisesi'nin kurucusu ve ilk Patriği olarak onurlandırılır. Kalıntıları, koruyucu olarak onurlandırıldığı Venedik'teki San Marco Bazilikası'nda saklanır.", "Mısır, Venedik, noterler, Kıpti Ortodoks Kilisesi"),
    ("April 28", "Saint Louis-Marie de Montfort", "Aziz Louis-Marie de Montfort", "Batı Fransa yoksulları arasındaki hararetli misyon vaazlarıyla ve derin Meryem maneviyatıyla tanınan Fransız rahip ve misyoner (1673-1716). 'Kutsal Bakire Meryem'e Gerçek Bağlılık' ve 'Tespih'in Sırrı' kitaplarını yazdı; Meryem aracılığıyla İsa'ya tam adanma uygulamasını teşvik etti; bu, Papa Yuhanna Pavlus II'nin 'Totus Tuus' papalık armasını etkiledi. Meryem Topluluğu'nu (Montfort Misyonerleri) ve Bilgelik Kızları'nı kurdu. 1947'de Papa XII. Pius tarafından aziz ilan edildi.", "Resmî koruyuculuk atanmamıştır; özellikle Meryem'e bağlılık ve misyon vaazı için onurlandırılır"),
    ("August 10", "Saint Lawrence of Rome", "Romalı Aziz Lawrence", "Papa II. Sixtus'un Roma'daki yedi diyakozundan biri; İmparator Valerianus zulmü sırasında 258'de şehit edildi. Gelenek, ondan Kilise'nin hazinelerini teslim etmesinin istendiğini, onun yerine hizmet ettiği Roma'nın yoksullarını ve hastalarını sunduğunu, bunun üzerine ızgarada kızartılarak öldürüldüğünü ve cellatlarına 'Beni çevirin, bu tarafım pişti' dediğini söyler. Erken Roma Kilisesi'nin en çok onurlandırılan şehitlerinden biridir.", "Aşçılar, yoksullar, kütüphaneciler, Roma şehri"),
    ("August 20", "Saint Bernard of Clairvaux", "Clairvaux'lu Aziz Bernard", "Vaazlarının ve yazılarının belagati nedeniyle 'Tatlı Dilli Doktor' denen Fransız Sistersiyen başrahip ve Kilise Doktoru. Clairvaux Manastırı'nı kurdu ve Sistersiyen tarikatının hızlı büyümesinin arkasındaki başlıca güç oldu; Ezgiler Ezgisi üzerine vaazları ve Meryem'e bağlılığı Orta Çağ maneviyatını şekillendirdi. 1830'da Papa VIII. Pius tarafından Kilise Doktoru ilan edildi.", "Arıcılar, mumcular, Burgundy, Cebelitarık"),
    ("August 9", "Saint Herman of Alaska", "Alaska'lı Aziz Herman", "Yaklaşık 1756'da Egor Popov olarak doğan, 1794'te Valaam Manastırı'ndan Rus Alaska'sına gönderilen ilk Ortodoks misyoner grubuna katılan Rus Ortodoks keşiş. Kodiak yakınındaki Spruce Adası'na yerleşip çilekeş bir sadelikle yaşadı, yetimlere baktı, yerli Alutiiq halkını eğitti ve onları Rus kürk tüccarlarının sömürüsüne karşı savundu; 'Alaska yerlilerinin Koruyucusu' unvanını kazandı. 1836'da öldü. 9 Ağustos 1970'te Amerika'daki Ortodoks Kilisesi tarafından aziz ilan edildi; Kuzey Amerika'da aziz ilan edilen ilk Ortodoks'tur.", "Alaska, Kuzey Amerika'daki Ortodoks misyonerler"),
    ("December 12", "Our Lady of Guadalupe", "Guadalupe Meryemi", "Meksika'daki Guadalupe Meryemi Bazilikası'nda onurlandırılan, Aralık 1531'de Tepeyac Tepesi'nde Aziz Juan Diego'ya Meryem'in görünüşlerini anan Meryem unvanı ve imajı. Kendi Nahuatl dilinde ona konuşan Meryem, o yere bir kilise yapılmasını istedi ve yerel piskopos Juan de Zumárraga için bir işaret olarak imajını mucizevi biçimde tilmasına (pelerinine) işledi; bugün Bazilika'da onurlandırılan ve dayanıklılığıyla incelenen bir imaj. Meksika'nın ve Amerika kıtalarının koruyucusudur; bayramı Amerika kıtalarında dünyanın en yaygın kutlanan Meryem bayramlarından biri olarak, özellikle Meksikalı ve Meksikalı-Amerikalı Katolikler arasında kutlanır.", "Meksika, Amerika kıtaları"),
    ("December 4", "Saint Barbara", "Aziz Barbara", "Katolik ve Doğu Ortodoks Kiliselerinde antik çağlardan beri onurlandırılan, üçüncü ya da dördüncü yüzyılda yaşadığı söylenen bakire şehit. Geleneğe göre putperest babası, onun gizli dönüşümünü öğrenince onu dünyadan uzak tutmak için bir kuleye hapsetti ve imanından vazgeçmeyi reddedince işkence edip başını kestirdi. Hikâyesi, zulmedenini bir fırtınanın çarpmasını anlatır; bu yüzden yıldırıma, yangına ve ani ölüme karşı yaygın biçimde ona yakarılır. Bayramı 1969'da evrensel Roma Takvimi'nden çıkarıldı ama birçok yerel Katolik takviminde hâlâ tutulur.", "Madenciler, topçular ve itfaiyeciler; yıldırım ve ani ölüme karşı"),
    ("December 9", "Saint Juan Diego", "Aziz Juan Diego", "Yaklaşık 1474'te Cuauhtlatoatzin olarak doğan Meksikalı yerli Chichimec dönmesi. Aralık 1531'de Meksiko yakınındaki Tepeyac Tepesi'nde, orada bir kilise yapılmasını isteyen ve imajını tilmasına (pelerin) mucizevi biçimde işleyen Meryem'in dört görünüşünü bildirdi; bu imaj şimdi Guadalupe Meryemi Bazilikası'nda saklanır. Hayatının kalanını orada inşa edilen şapelin alçakgönüllü bekçisi olarak geçirdi. 1548'de öldü, 1990'da mübarek, 2002'de Papa Yuhanna Pavlus II tarafından aziz ilan edildi; Amerika kıtalarının yerlisi ilk azizdir.", "Amerika kıtalarının yerli halkları, Meksika"),
    ("February 10", "Saint Scholastica", "Aziz Scholastica", "Nursia'lı Aziz Benedictus'un ikiz kız kardeşi ve Benedikten rahibelerin kurucusu. Kardeşinin Monte Cassino manastırının yakınında dinî kadınlardan oluşan bir topluluk kurdu. Aziz Gregorius'a göre son görüşmelerinde, kutsal sohbetleri gece boyunca sürsün diye Benedictus'un ayrılmasını engellemek için fırtına çıkması için dua etti; üç gün sonra öldü ve Benedictus onun ruhunun bir güvercin biçiminde göğe yükseldiğini gördü.", "Rahibeler, Benedikten manastırlar, fırtınalara karşı"),
    ("February 11", "Our Lady of Lourdes", "Lourdes Meryemi", "Fransa'daki Lourdes'ta Massabielle Mağarası'nda 11 Şubat 1858'den başlayarak on dört yaşındaki Bernadette Soubirous'a Kutsal Bakire Meryem'in on sekiz görünüşünü anan Meryem unvanı. Meryem kendini Bernadette'e 'Ben Lekesiz Gebe Kalışım' diyerek tanıttı, bir şapel yapılmasını ve inananların oraya geçit töreniyle gelmesini istedi. Görünüşler sırasında mağarada fışkıran bir pınar, o günden beri şifa arayan milyonlarca hacıyı çekti; hac yeri dünyanın en çok ziyaret edilen Meryem hac yerlerinden biri olmayı sürdürür. Papa Yuhanna Pavlus II, Dünya Hastalar Günü'nü bu bayramda her yıl kutlanmak üzere kurdu.", "Hastalar, Lourdes, Fransa"),
    ("February 14", "Saints Cyril and Methodius", "Aziz Cyril ve Aziz Methodius", "Selanik'ten dokuzuncu yüzyıl Bizans Yunan kardeşleri; 'Slavların Havarileri' olarak anılır, Büyük Moravya'nın Slav halklarına Hıristiyanlığı ve Kutsal Yazılar'ı getirdiler. Cyril, Litürji ve Kutsal Kitap Eski Kilise Slavcası'na çevrilebilsin diye adını taşıyan Kiril alfabesinin öncüsü Glagolitik alfabeyi geliştirdi. Papa Yuhanna Pavlus II onları 1980'de Aziz Benedictus ile birlikte Avrupa'nın eş koruyucuları ilan etti. Doğu Ortodoks Kilisesi'nde de 'Havarilerle Eşit' olarak onurlandırılırlar ve asıl bayramlarını 11 Mayıs'ta tutarlar.", "Avrupa, Slav halkları, ekümenizm"),
    ("February 18", "Martin Luther", "Martin Luther", "İndüljans satışına meydan okuyan 1517 Doksan Beş Tezi'yle Protestan Reformu'nu başlatan Alman Augustinian keşiş ve ilahiyatçı. Kutsal Kitap'ı Almancaya çevirdi, Küçük İlmihal ve Büyük İlmihal'i yazdı ve 'Sağlam Kale Tanrımızdır' dahil çok sayıda ilahi besteledi. 18 Şubat 1546'da Almanya'nın Eisleben kentinde öldü. Aziz ilan edilmemiştir ve şefaat için yakarılmaz; ancak Lutheran kiliseler ve bazı diğer Batı takvimleri onu Kilise'nin yenileyicisi ve imanın öğretmeni olarak ölüm gününde her yıl anar.", "Reformcu ve imanın öğretmeni olarak Lutheran kiliselerce anılır"),
    ("February 27", "Saint Gregory of Narek", "Narek'li Aziz Gregory", "Aidiyetini taşıdığı Ermeni Apostolik Kilisesi'nde başlıca onurlandırılan, onuncu yüzyıl Ermeni keşişi, mistiği ve şair-ilahiyatçısı. Narek manastırında keşiş olan kendisi, derin kişisel pişmanlığı mistik ilahiyatla harmanlayan tövbe duaları derlemesi 'Ağıtlar Kitabı' (Narek) ile bilinir; bugün Ermeni evlerinde hâlâ okunur. 2015'te Papa Franciscus onu Evrensel Kilise Doktoru ilan etti; bu unvanı alan ilk Ermeni ve Roma ile tam bağlantıda olmayan ilk azizdir; 2021'de isteğe bağlı anmasını bu tarihte Genel Roma Takvimi'ne ekledi.", "Resmî koruyuculuk atanmamıştır; özellikle Ermeni Hıristiyanlar arasında onurlandırılır"),
    ("February 6", "Saint Xenia of Saint Petersburg", "Saint Petersburg'lu Aziz Xenia", "Kocası Andrei'nin yaklaşık 1748'de ani ölümünden sonra tüm eşyasını veren, onun adını ve kimliğini alan ve yaklaşık kırk beş yıl Saint Petersburg sokaklarında yoksulluk, dua ve gizli hayır işleriyle dolaşan Rus Ortodoks 'Mesih uğruna deli'. Smolensk Mezarlığı kilisesinin yapımına geceleri gizlice tuğla taşıyarak yardım ettiği söylenir. Kendisini arayanlara yol gösteren ve teselli eden peygamberce sözleriyle tanındı. 1988'de Rus Ortodoks Kilisesi tarafından aziz ilan edildi.", "Yoksullar ve evsizler, eş ya da aile istikrarı arayanlar, Saint Petersburg"),
    ("January 14", "Saint Nino of Georgia", "Gürcistan'lı Aziz Nino", "Gürcistan'ın Havarilerle Eşit Aydınlatıcısı; başlıca Doğu Ortodoks ve Oryantal Ortodoks geleneklerinde onurlandırılır. Yaklaşık 296'da Kapadokya'da doğan ve Aziz George'un akrabası olduğu söylenen Nino, asmalardan bağlanmış bir haçla İberya Krallığı'na (bugünkü Gürcistan) gitti; vaazları ve şifalarıyla Kral III. Mirian ve Kraliçe Nana'yı Hıristiyanlığı kabul etmeye yöneltti ve Gürcistan'ın dördüncü yüzyılın başında Hıristiyan bir ulus olarak dönüşümünü sağladı. Yaklaşık 338-340'ta öldü ve bugün hâlâ Gürcistan'da büyük bir hac yeri olan Bodbe Manastırı'na gömüldü.", "Gürcistan ve Gürcü Ortodoks Kilisesi"),
    ("January 2", "Saint Gregory Nazianzen", "Nazianzos'lu Aziz Gregorius", "İstanbul Başpiskoposu ve Kilise Doktoru; Roma Katolik takviminde bu bayramda Büyük Aziz Basil ile birlikte onurlandırılır. Üç Kapadokyalı Baba'dan biri olan kendisi, 381'de Birinci İstanbul Konsili'nde Mesih'in ve Kutsal Ruh'un tanrılığını Ariusçuluğa karşı derinlemesine savunduğu için 'İlahiyatçı' diye anılır. Doğu Ortodoks Kilisesi'nde Büyük Aziz Basil ve Aziz Yuhanna Chrysostomos ile birlikte Üç Kutsal Hiyerark'tan biri olarak onurlandırılır.", "İlahiyatçılar, Kapadokya"),
    ("January 2", "Saint John of Kronstadt", "Kronstadt'lı Aziz Yuhanna", "Saint Petersburg yakınındaki Kronstadt'ta Aziz Andreas Katedrali'nde elli yıldan fazla hizmet eden, günlük İlahi Litürji'yi kutlayan ve hararetli duası, bildirilen şifa armağanları ve ruhsal danışmanlığıyla büyük kalabalıklar çeken Rus Ortodoks rahibi (1829-1908). Önemli gelirinin büyük bölümünü yoksullar için bir 'Çalışkanlık Evi' ve diğer hayır kurumları kurmaya harcadı; 'Mesih'te Hayatım' adıyla yayımlanan ruhsal günlüğü hâlâ yaygın biçimde okunur. 1964'te Rusya Dışı Rus Ortodoks Kilisesi, 1990'da Moskova Patrikhanesi tarafından aziz ilan edildi.", "Rahipler, yoksullar, Kronstadt"),
    ("July 11", "Saint Olga of Kiev", "Kiev'li Aziz Olga", "Onuncu yüzyılda Kiev Rus'unun Büyük Prensesi ve naibi; Büyük Aziz Vladimir'in büyükannesi. Kocası Prens Igor'un ölümünden sonra oğulları için naip olarak hüküm sürdü, sonra İstanbul'a gitti, orada vaftiz edilip Hıristiyanlığı kabul eden ilk Rus hükümdarı oldu; ancak devletin tamamı torunu döneminde Hıristiyanlaştırıldı. Rus topraklarına İncil'i getirmedeki rolü nedeniyle Doğu Ortodoks Kilisesi tarafından 'Havarilerle Eşit' unvanıyla onurlandırılır.", "Dullar, din değiştirenler, Rusya ve Ukrayna"),
    ("July 12", "Saint Paisios of Mount Athos", "Athos Dağı'ndan Aziz Paisios", "1924'te Kapadokya'da Arsenios Eznepidis olarak doğan Athos Kutsal Dağı'nın Yunan Ortodoks keşişi ve ruhsal yaşlısı. Alçakgönüllülüğü, çilekeş yaşamı ve ruhsal danışmanlık armağanıyla Ortodoks dünyasında tanınan kendisi, son on yıllarını Koutloumousiou Manastırı yakınındaki Panagouda hücresinde kendisini arayan binlerce hacıya rehberlik ederek geçirdi. 1994'te öldü ve Ocak 2015'te İstanbul Ekümenik Patrikhanesi tarafından aziz ilan edildi.", "Athos Dağı, keşişler, ruhsal rehberlik"),
    ("July 15", "Saint Vladimir the Great", "Büyük Aziz Vladimir", "988'de Kırım'daki Chersonesos'ta kendisi vaftiz olup Bizans prensesi Anna ile evlendikten sonra Hıristiyanlığı Kiev Rus'unun resmî dini olarak benimseyen ('Rus'un Vaftizi') Kiev Büyük Prensi. Aziz Olga'nın torunu olarak halkını Dinyeper Nehri'nde toplu halde vaftiz ettirdi, imanı yaymak, kiliseler inşa etmek ve önceki saltanatındaki putperest uygulamalara son vermek için çalıştı. Rus'un vaftizcisi olarak Doğu Ortodoks Kilisesi'nce 'Havarilerle Eşit' unvanıyla onurlandırılır.", "Rusya, Ukrayna ve Rus halkları, din değiştirenler"),
    ("July 24", "Saint Charbel Makhlouf", "Aziz Charbel Makhlouf", "1828'de Lübnan'ın Bekaa Kafra kasabasında Youssef Antoun Makhlouf olarak doğan Lübnanlı Maruni Katolik keşiş ve münzevi. Lübnan Maruni Tarikatı'na girip erken bir şehidin adı olan Charbel adını aldı; Annaya'daki Aziz Maron Manastırı'nda yıllarca keşişlikten sonra hayatının son 23 yılını yakınlarda Efkaristiya'ya, duaya ve aşırı çilekeşliğe adanmış bir münzevi olarak geçirdi. 24 Aralık 1898'de öldü; bedeni sonradan bozulmamış bulundu ve mezarında binlerce şifa bildirildi. Papa VI. Paulus onu 1965'te mübarek, 1977'de aziz ilan etti.", "Lübnan; hastaların şifası için yaygın biçimde yakarılır"),
    ("June 27", "Saint Cyril of Alexandria", "İskenderiyeli Aziz Cyril", "412-444 arasında İskenderiye Patriği ve Kilise Doktoru; 431'deki Efes Konsili'nde Nestorius'a karşı Kutsal Bakire Meryem için 'Theotokos' (Tanrı'nın Anası) unvanının başlıca savunucusu oldu ve Kilise'nin Mesih'in tanrısal ve insani doğalarının tek Kişi'de birliği hakkındaki öğretisini şekillendirdi. Papaları arasında saydığı ve 'İman Direği' unvanıyla onurlandırdığı Kıpti Ortodoks Kilisesi'nde özellikle saygı görür.", "İlahiyatçılar"),
    ("June 5", "Saint Boniface", "Aziz Boniface", "'Almanların Havarisi' olarak bilinen İngiltere doğumlu Benedikten keşiş ve misyoner piskopos. Putperest Germen halklarını müjdelemek için İngiltere'den ayrıldı; Mesih'in gücünün işareti olarak Geismar'daki kutsal Thor Meşesi'ni kesmesiyle ünlüdür; Frank topraklarında piskoposlukları yeniden düzenledi ve Fulda manastırı dahil manastırlar kurdu. Müridleri onay için hazırlarken Frizya'da putperest akıncılarca birkaç arkadaşıyla birlikte 754'te şehit edildi.", "Almanya"),
    ("June 9", "Saint Columba of Iona", "Iona'lı Aziz Columba", "Kraliyet Uí Néill soyundan İrlandalı başrahip ve misyoner (yaklaşık 521-597); yaklaşık 563'te on iki arkadaşıyla İrlanda'dan ayrılıp İskoçya kıyısındaki Iona adasında bir manastır kurdu. Bu ada topluluğundan İskoçya'nın Piktlerini müjdeledi ve Iona, ölümünden sonra yüzyıllarca Britanya Adaları'nda büyük bir öğrenim ve misyon merkezi oldu. 'İrlanda'nın On İki Havarisi' arasında sayılır; özellikle İrlanda ve İskoçya'da onurlandırılır.", "Resmî koruyuculuk atanmamıştır; özellikle İrlanda ve İskoçya'da onurlandırılır"),
    ("June 9", "Saint Ephrem the Syrian", "Süryani Aziz Ephraim", "Ariusçu ve Gnostik öğretiye karşı İznik ortodoksluğunu savunan yüzlerce ilahi besteleyerek 'Kutsal Ruh'un Çiftesi' (Lir) unvanını alan Süryani diyakoz, şair ve Kilise Doktoru. Nusaybin ve sonra Urfa Kilisesi'ne hizmet etti; öğretmeye, kıtlıkta yardıma ve kutsal şiire adanmış çilekeş bir hayat yaşadı. 1920'de Papa XV. Benedictus tarafından Kilise Doktoru ilan edildi; Doğu ve Oryantal Ortodoks Kiliselerinde de çok saygı görür.", "Ruhsal rehberler, ruhsal önderler, Süryani Hıristiyanlar"),
    ("March 18", "Saint Cyril of Jerusalem", "Kudüslü Aziz Cyril", "Dördüncü yüzyılda Kudüs Piskoposu ve Kilise Doktoru; en iyi, vaftize hazırlananlara verilen ve erken Hıristiyan litürjisi ve öğretisinin kilit tanığı olmayı sürdüren Katekizm Dersleri ile hatırlanır. Öğretisi Birinci İstanbul Konsili'nde haklı çıkmadan önce Ariusçu tartışmalar sırasında tekrarlanan sürgünlere dayandı. 1883'te Papa XIII. Leo tarafından Kilise Doktoru ilan edildi.", "İlmihal öğretmenleri, vaftize hazırlananlar"),
    ("March 30", "Saint John Climacus", "Merdivenli Aziz Yuhanna (Klimakos)", "Altıncı ve yedinci yüzyıllarda Sina Dağı'ndaki Aziz Catherine Manastırı'nın keşişi ve başrahibi; hem Doğu hem Batı Hıristiyanlığında ruhsal yaşamın ustası olarak onurlandırılır. En iyi, bir ruhun Tanrı'yla birliğe doğru tırmandığı otuz erdem basamağını anlatan klasik 'İlahi Yükseliş Merdiveni' ile bilinir; Doğu Ortodoks ve Bizans Katolik geleneklerinde Büyük Oruç sırasında manastırlarda sesli okunur.", "Keşişler ve manastır yaşayanlar"),
    ("March 7", "Saints Perpetua and Felicity", "Aziz Perpetua ve Aziz Felicity", "Yaklaşık 203'te Septimius Severus zulmü sırasında amfitiyatroda öldürülen Kartaca'nın erken Hıristiyan şehitleri. Genç bir soylu kadın ve yeni anne olan Perpetua, görümlerini ve babasının yalvarmalarına rağmen Mesih'i inkâr etmeyi reddedişini anlatan bir hapishane günlüğü tuttu; imandaki arkadaşı ve hamile kölesi Felicity, şehitlikten kısa süre önce doğum yaptı ve onunla birlikte idam edildi. Onların hikâyesi, 'Aziz Perpetua ve Felicity'nin Çilesi', Hıristiyan şehitliğinin en eski ve canlı kayıtlarındandır.", "Hamile kadınlar, Kartaca"),
    ("May 24", "John Wesley", "John Wesley", "Kardeşi Charles ile birlikte İngiltere Kilisesi içinde Metodist hareketi kuran İngiliz Anglikan rahip ve müjdeci. Oxford eğitimli bir din adamı olan kendisi, 24 Mayıs 1738'de Londra'da Aldersgate Sokağı'ndaki bir toplantıda Tanrı'nın lütfundan derin bir güvence deneyimi yaşadı; ardından Britanya boyunca yorulmadan vaaz verdi ve din değiştirenleri karşılıklı hesap verebilirlik ve kutsallıkta büyüme için küçük 'derneklerde' örgütledi. Çok sayıda vaaz ve ilahiyat eseri yazdı. 1791'de öldü. Aziz ilan edilmemiştir ama İngiltere Kilisesi ve dünya genelindeki Metodist kiliseler onu ve Charles Wesley'i 24 Mayıs'ta birlikte anar.", "Metodist ve Anglikan kiliselerce müjdeci ve Metodist hareketin kurucusu olarak anılır"),
    ("May 24", "Saint Charles Wesley", "Aziz Charles Wesley", "John Wesley'nin küçük kardeşi, onunla birlikte İngiltere Kilisesi içindeki Metodist hareketin kurucusu olan İngiliz Anglikan din adamı ve bereketli ilahi yazarı. Yaşamı boyunca birkaç bin ilahi yazdı; bunlar arasında birçok mezhepte ibadetin merkezinde kalan 'Hark! The Herald Angels Sing', 'O for a Thousand Tongues to Sing' ve 'Christ the Lord Is Risen Today' bulunur. 1788'de öldü. Aziz ilan edilmemiştir ama İngiltere Kilisesi ve dünya genelindeki Metodist kiliseler onu kardeşi John ile birlikte 24 Mayıs'ta anar.", "Metodist ve Anglikan kiliselerce ilahi yazarı ve Metodist hareketin kurucusu olarak anılır"),
    ("November 14", "Saint Gregory Palamas", "Aziz Gregory Palamas", "Yaklaşık 1296'da İstanbul'da doğan, Selanik Başpiskoposu (1347'de atandı) olan Bizans Ortodoks keşişi ve ilahiyatçısı. Parlak bir saray kariyerini bırakıp Athos Dağı'nda keşiş oldu ve aralıksız iç duanın hesikast geleneğini benimsedi. Kalabriyalı keşiş Barlaam hesikazmı batıl inanç diye saldırınca, Palamas onu 'Kutsal Hesikastlar İçin Savunma'sında savundu; Tanrı'nın bilinemez özü ile müminlerin ilahi lütfu gerçekten deneyimlediği yaratılmamış enerjileri arasındaki ayrımı açıkladı; bu Ortodoks ilahiyatının temel bir öğretisidir. 1359'da öldü ve 1368'de aziz ilan edildi.", "Ortodoks ilahiyatçılar, hesikastlar, Athos Dağı"),
    ("November 15", "Saint Albert the Great", "Büyük Aziz Albertus", "Felsefe, ilahiyat ve doğa bilimlerindeki bilgisinin genişliği nedeniyle 'Evrensel Doktor' denen Dominikan keşiş, piskopos ve Kilise Doktoru. Aziz Thomas Aquinas'ın Paris ve Köln üniversitelerindeki öğretmeniydi; Aristoteles felsefesini Hıristiyan imanıyla uzlaştırmaya çalıştı ve botanik, zooloji, mineraloji ve astronomi üzerine kapsamlı yazılar yazdı. 1931'de Papa XI. Pius tarafından aziz ilan edildi ve Kilise Doktoru ilan edildi; Papa XII. Pius sonradan onu doğa bilimcilerinin koruyucusu seçti.", "Doğa bilimcileri ve filozoflar"),
    ("November 25", "Saint Catherine of Alexandria", "İskenderiyeli Aziz Catherine", "Dördüncü yüzyılın başındaki bakire şehit; antik çağlardan beri Mısır'ın İskenderiye kentinde Hıristiyanlığa geçen ve imanı savunmak için putperest filozoflarla alenen tartışan bilgin soylu bir kadın olarak onurlandırılır. Geleneğe göre İmparator Maxentius tarafından dikenli bir tekerlekte parçalanmaya mahkûm edildi; tekerleğin onun dokunuşuyla paramparça olduğu söylenir; sonra başı kesildi. Ona bağlılık hem Doğu'da hem Batı'da yaygınlaştı; Sina Dağı'nın eteğindeki en eski Hıristiyan manastırlarından biri olan Aziz Catherine Manastırı adını taşır.", "Filozoflar, ilahiyatçılar ve öğrenciler; bekâr kadınlar; tekerlek ustaları"),
    ("October 16", "Saint Margaret Mary Alacoque", "Aziz Margaret Mary Alacoque", "Paray-le-Monial'daki Meryem'in Ziyareti Tarikatı'nın Fransız rahibesi; 1673-1675 arasında İsa'nın Kutsal Kalbi'ni açıkladığı, onun onuruna bir bayram, İlk Cuma günlerinde Kutsal Komünyon alma uygulaması ve Perşembe geceleri Bahçe'deki Ağıtı'nın anısına Kutsal Ekmek önünde bir saatlik dua istediği bir dizi vizyon aldı. Ruhsal yöneticisi Aziz Claude de la Colombière tarafından yönlendirilerek, Katolik Kilisesi'ne yayılan İsa'nın Kutsal Kalbi'ne bağlılığın kurulmasına yardım etti. 1690'da öldü ve 1920'de Papa XV. Benedictus tarafından aziz ilan edildi.", "İsa'nın Kutsal Kalbi'ne bağlılık; çocuk felci hastaları"),
    ("September 16", "Saint Cyprian of Carthage", "Kartaca'lı Aziz Cyprianus", "Kuzey Afrika'daki Kartaca Piskoposu ve üçüncü yüzyılın en etkili Latin Kilise Babalarından biri. Eski bir hatip olan kendisi yaklaşık 246'da Hıristiyanlığa geçti ve iki yıl içinde piskopos seçildi. Kartaca Hıristiyanlarını Decius zulmünden ve imanı terk edenler krizinden geçirdi; 'Katolik Kilisesi'nin Birliği Üzerine' risalesi Kilise birliği ve piskoposların yetkisi konusunda temel bir ifade olmayı sürdürür. İmparator Valerianus zulmü sırasında tutuklandı ve Roma tanrılarına kurban sunmayı reddederek 258'de Kartaca dışında başı kesildi; Afrika'nın ilk piskopos-şehitlerinden biri oldu. Hem Batı hem Doğu Kiliseleri tarafından anılır.", "Kuzey Afrika, Kartaca"),
    ("September 17", "Saint Hildegard of Bingen", "Bingen'li Aziz Hildegard", "On ikinci yüzyılın Alman Benedikten başrahibesi, mistiği, bestecisi ve çok yönlü bilginiydi. Görümlerini ışıklı Scivias eserinde kaydetti, bugün hâlâ icra edilen litürjik müzikler besteledi ve doğa tarihi ve tıp üzerine kapsamlı yazılar yazdı. Papa XVI. Benedictus 2012'de onu Kilise Doktoru ilan etti; bu unvanı taşıyan çok az kadından biridir.", "Müzisyenler, yazarlar, doğa bilimcileri"),
]
